function updateCalendars() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var data = sheet.getDataRange().getValues();

  // Skip header row
  for (var i = 1; i < data.length; i++) {
    var guestName = data[i][0];
    var eventTitle = data[i][1];
    var startTime = data[i][2];
    var endTime = data[i][3];
    var location = data[i][4];
    var description = data[i][5];

    // Get or create individual calendar
    var calendarId = getOrCreateCalendar(guestName);

    // Create event in the calendar
    var event = {
      summary: eventTitle,
      location: location,
      description: description,
      start: {
        dateTime: new Date(startTime),
        timeZone: 'America/New_York'
      },
      end: {
        dateTime: new Date(endTime),
        timeZone: 'America/New_York'
      }
    };

    CalendarApp.getCalendarById(calendarId).createEvent(event.summary, event.start.dateTime, event.end.dateTime, {description: event.description, location: event.location});
  }
}

function getOrCreateCalendar(guestName) {
  var calendars = CalendarApp.getAllCalendars();
  for (var i = 0; i < calendars.length; i++) {
    if (calendars[i].getName() === guestName) {
      return calendars[i].getId();
    }
  }
  // Create new calendar if it doesn't exist
  var newCalendar = CalendarApp.createCalendar(guestName);
  return newCalendar.getId();
}
```

