  for (var i = 0; i < calendars.length; i++) {
    if (calendars[i].getName() === guestName) {
      return calendars[i].getId();
    }
  }
  // Create new calendar if it doesn't exist
  var newCalendar = CalendarApp.createCalendar(guestName);
  return newCalendar.getId();
}

function findExistingEvent(calendarId, eventTitle, startTime, endTime) {
  var calendar = CalendarApp.getCalendarById(calendarId);
  var events = calendar.getEvents(new Date(startTime), new Date(endTime));

  for (var i = 0; i < events.length; i++) {
    if (events[i].getTitle() === eventTitle) {
      return events[i];
    }
  }

  return null;
}

