function setupTriggers() {
  ScriptApp.newTrigger('updateCalendars')
      .timeBased()
      .everyDays(1)
      .atHour(0)
      .create();

  ScriptApp.newTrigger('updateCalendars')
      .forSpreadsheet(SpreadsheetApp.getActiveSpreadsheet())
      .onEdit()
      .create();
}
